/* Skill tip mockup (not game code). Data: data.js (real describeSkill output + real bandTipHtml, generated by a throwaway script), rules.js (the shortening rules). */
(function () {
  'use strict';
  var D = window.ST_DATA, ST = D.stats;
  var $ = function (s, r) { return (r || document).querySelector(s); };
  var esc = function (s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); };
  var SIZES = { '169': { w: 1920, h: 1080, hs: 1, label: '16:9' }, '219': { w: 2580, h: 1080, hs: 1, label: '21:9' }, ph: { w: 844, h: 390, hs: 390 / 1080, label: 'Phone 844x390' } };
  var SKEY = ['judgment', 'double', 'charge', 'brand'];
  var VNAME = { now: 'Now', a: 'A', b: 'B', c: 'C' };
  var S = { z: '169', v: null, s: 0, clean: false, cover: true, o: false };
  var I = 'skill-tips/i/';

  /* ---------- hash ---------- */
  function readHash() {
    location.hash.slice(1).split('&').forEach(function (p) {
      if (!p) return;
      var kv = p.split('='), k = kv[0], v = kv[1];
      if (k === 'now' || k === 'a' || k === 'b' || k === 'c') S.v = k;
      else if (k === 'clean') S.clean = true;
      else if (k === 'nocover') S.cover = false;
      else if (k === 'o') S.o = v !== '0';
      else if (k === 'z' && SIZES[v]) S.z = v;
      else if (k === 's') { var i = SKEY.indexOf(v); if (i < 0) D.samples.forEach(function (x, j) { if (x.id === v) i = j; }); if (i >= 0) S.s = i; }
    });
  }
  function writeHash() {
    var h = (S.v ? S.v : '') + (S.v ? '&' : '') + 'z=' + S.z + '&s=' + SKEY[S.s] + (S.o ? '&o=1' : '') + (S.clean ? '&clean' : '') + (S.cover ? '' : '&nocover');
    try { history.replaceState(null, '', '#' + h); } catch (e) { /* file:// may refuse */ }
  }

  /* ---------- tip html per sample / variant / tier ---------- */
  function tipOf(sm, v, open) {
    var h = sm.html;
    if (v === 'now') return h.now;
    if (v === 'a') return open && h.a2 ? h.a2 : h.a1;
    if (v === 'b') return open && h.b2 ? h.b2 : h.b1;
    return h.c;
  }
  function hasTier2(sm, v) { return (v === 'a' && !!sm.html.a2) || (v === 'b' && !!sm.html.b2); }

  /* ---------- the real bottom bar (plates use the real classes of src/ui/skill-bar.ts) ---------- */
  function chipHtml(cls, icon, word, num) { return '<span class="bp-chip ' + cls + '"><img class="bh-ico" src="' + icon + '" alt="">' + (word ? '<span class="w">' + word + '</span>' : '') + '<b>' + num + '</b></span>'; }
  function plateHtml(p, key, tipInner, hot) {
    var chips = '';
    if (p.free) chips += '<span class="bp-chip free">Free</span>';
    if (p.mp) chips += chipHtml('', I + 'mp.webp', '', p.mp);
    if (p.rage) chips += chipHtml('rage', I + 'rage.webp', 'RAGE', (/(\d+)/.exec(p.rage) || [0, '30'])[1]);
    if (p.cd) chips += chipHtml('cd', I + 'cooldown.webp', '', p.cd);
    var tag = p.ult ? '<span class="bp-tag"><span class="full">Ultimate</span><span class="short">Ult</span></span>' : '';
    return '<div class="bp ' + (p.ult ? 'ult' : '') + (hot ? ' tip' : '') + '" data-skill="' + p.id + '">' + tag + '<span class="bp-key">' + key + '</span><div class="bp-ico"><img class="bh-ico" src="' + I + 'sk-' + p.icon + '.webp" alt=""></div><span class="bp-nm">' + esc(p.name) + '</span><div class="bp-chips">' + chips + '</div>' +
      '<div class="bh-sktip bh-panel bh-corners" data-tipbox="1">' + (hot ? tipInner : '') + '</div></div>';
  }
  var uid = 0;
  function frameHtml(si, v, open, tagText) {
    var sm = D.samples[si], cls = D.classes[sm.cls], z = SIZES[S.z], phone = S.z === 'ph';
    var viewW = z.w / z.hs, PW = phone ? 146 : 132, PG = 8;
    var sx0 = viewW / 2 - (4 * PW + 3 * PG) / 2, SKW = 4 * PW + 3 * PG;
    var plates = cls.plates.map(function (p, i) { return plateHtml(p, i + 1, tipOf(sm, v, open), i === sm.slot); }).join('');
    var pas = '<div class="bp pas"><span class="bp-tag"><span class="full">Passive</span><span class="short">Pas</span></span><div class="bp-ico"><img class="bh-ico" src="' + I + 'sk-' + cls.passive.icon + '.webp" alt=""></div><span class="bp-nm">' + esc(cls.passive.name) + '</span><div class="bp-chips"></div></div>';
    var gx = sx0 + SKW + (phone ? 12 : 22);
    var glob = '<div class="sf-glob" style="left:' + gx + 'px"><div><img src="' + I + 'rest.webp" alt="">Rest</div><div><img src="' + I + 'skip.webp" alt="">Skip</div><div><img src="' + I + 'move.webp" alt="">Move</div></div>';
    var actor = '<div class="sf-actor" style="left:' + (phone ? 20 : 28) + 'px"><img src="' + I + 'av-' + sm.cls + '.webp" alt=""><span>' + esc(cls.name) + '</span></div>';
    var id = 'f' + (uid++);
    return '<div class="fr-wrap" data-s="' + si + '" data-v="' + v + '" data-open="' + (open ? 1 : 0) + '" id="' + id + '"><div class="cap">' + esc(tagText) + '<small>' + esc(sm.label) + ' &middot; ' + z.label + '</small></div>' +
      '<div class="sf"><div class="sf-in" style="width:' + z.w + 'px;height:' + z.h + 'px"><div class="sf-bg"></div>' +
      '<div class="bh-root" style="width:' + viewW + 'px;height:1080px;transform:scale(' + z.hs + ');--bh-inv:' + (1 / z.hs) + '"><div class="bh-band"></div>' + actor + '<div class="bh-pasv" style="left:' + (sx0 - (PW + PG)) + 'px;width:' + PW + 'px">' + pas + '</div><div class="bh-skills" style="left:' + sx0 + 'px">' + plates + '</div>' + glob + '</div>' +
      '<div class="sf-cover"></div></div></div></div>';
  }

  /* ---------- layout: scale every frame to its column, draw the covered rectangle ---------- */
  function layoutFrames() {
    document.querySelectorAll('.fr-wrap').forEach(function (w) {
      var sf = $('.sf', w), inn = $('.sf-in', w), z = SIZES[S.z];
      var cw = w.clientWidth, k = cw / z.w;
      sf.style.width = cw + 'px'; sf.style.height = (z.h * k) + 'px';
      inn.style.transform = 'scale(' + k + ')';
      inn.dataset.k = k;
      var tip = $('.bh-sktip .bt', w), cov = $('.sf-cover', w);
      if (!tip) return;
      var a = inn.getBoundingClientRect(), r = tip.getBoundingClientRect();
      var x = (r.left - a.left) / k, y = (r.top - a.top) / k, ww = r.width / k, hh = r.height / k;
      cov.style.left = x + 'px'; cov.style.top = y + 'px'; cov.style.width = ww + 'px'; cov.style.height = hh + 'px';
      cov.style.borderWidth = Math.max(2, 2 / k) + 'px';
      var share = (ww * hh) / (z.w * z.h) * 100;
      var label = $('.cap small', w);
      if (label && !label.dataset.done) { label.dataset.done = 1; }
      label.innerHTML = esc(D.samples[+w.dataset.s].label) + ' &middot; ' + z.label + ' &middot; tip covers <b>' + share.toFixed(1) + '%</b> of the screen (' + Math.round(hh / z.h * 100) + '% of its height)';
    });
  }

  /* ---------- coverage table (measured with the real CSS, offscreen) ---------- */
  function measure() {
    var out = {}, root = document.documentElement, wasShort = root.classList.contains('short');
    var host = document.createElement('div');
    host.style.cssText = 'position:fixed;left:-20000px;top:0;visibility:hidden;width:3000px;height:1200px';
    document.body.appendChild(host);
    ['169', '219', 'ph'].forEach(function (zk) {
      var z = SIZES[zk]; root.classList.toggle('short', zk === 'ph');
      host.innerHTML = '<div class="bh-root" style="position:absolute;left:0;top:0;width:' + (z.w / z.hs) + 'px;height:1080px;transform:scale(' + z.hs + ');transform-origin:0 0;--bh-inv:' + (1 / z.hs) + '"><div class="bh-kit" id="mz" style="position:absolute;left:0;top:0"></div></div>';
      var box = $('#mz', host);
      D.samples.forEach(function (sm, si) {
        ['now', 'a1', 'a2', 'b1', 'b2', 'c'].forEach(function (key) {
          var html = sm.html[key]; if (!html) return;
          box.innerHTML = '<div class="bh-sktip">' + html + '</div>';
          var t = $('.bt', box), r = t.getBoundingClientRect();
          var w = r.width / z.hs, h = r.height / z.hs;
          (out[si + key] = out[si + key] || {})[zk] = { w: Math.round(w), h: Math.round(h), share: w * h / ((z.w / z.hs) * 1080) * 100, hs: h / 1080 * 100 };
        });
      });
    });
    root.classList.toggle('short', wasShort);
    host.remove();
    return out;
  }
  function coverageTable() {
    var M = measure(), rows = '';
    var names = { now: 'Now', a1: 'A  tier 1', a2: 'A  More open', b1: 'B  tier 1', b2: 'B  chip open', c: 'C' };
    var sums = {};
    D.samples.forEach(function (sm, si) {
      ['now', 'a1', 'a2', 'b1', 'b2', 'c'].forEach(function (key) {
        var m = M[si + key]; if (!m) return;
        rows += '<tr><td>' + esc(sm.label) + '</td><td>' + names[key] + '</td>' + ['169', '219', 'ph'].map(function (zk) { return '<td class="n">' + m[zk].share.toFixed(1) + '% <span style="color:var(--dim)">(' + m[zk].w + 'x' + m[zk].h + ', ' + Math.round(m[zk].hs) + '% high)</span></td>'; }).join('') + '</tr>';
        if (key !== 'a2' && key !== 'b2') { var kk = key.charAt(0); (sums[kk] = sums[kk] || { n: 0, z: { '169': 0, '219': 0, ph: 0 } }).n++; ['169', '219', 'ph'].forEach(function (zk) { sums[kk].z[zk] += m[zk].share; }); }
      });
    });
    var mean = ['now', 'a', 'b', 'c'].map(function (k) { var s = sums[k]; return '<tr><td><b>Mean of 4 skills</b></td><td><b>' + VNAME[k] + ' (closed)</b></td>' + ['169', '219', 'ph'].map(function (zk) { return '<td class="n"><b>' + (s.z[zk] / s.n).toFixed(1) + '%</b></td>'; }).join('') + '</tr>'; }).join('');
    return '<table class="t"><tr><th>Skill</th><th>State</th><th>16:9</th><th>21:9</th><th>Phone 844x390</th></tr>' + rows + mean + '</table>';
  }

  /* ---------- text blocks ---------- */
  function statRow(label, key) {
    var a = ST.all, c = ST['class'];
    function cell(o) { return '<td class="n">' + o.rowsAvg + ' / ' + o.rowsMed + ' / ' + o.rowsP90 + ' / ' + o.rowsMax + '</td><td class="n">' + o.charsAvg + ' / ' + o.charsMed + ' / ' + o.charsP90 + ' / ' + o.charsMax + '</td><td class="n">' + o.over4 + '</td>'; }
    return '<tr><td>' + label + '</td>' + cell(a[key]) + cell(c[key]) + '</tr>';
  }
  function statsTable() {
    return '<table class="t"><tr><th rowspan="2">Rule</th><th colspan="3">All ' + ST.all.now.n + ' skills (class + mobs + summons)</th><th colspan="3">Class skills only (' + ST['class'].now.n + ')</th></tr><tr><th>rows avg/med/p90/max</th><th>chars avg/med/p90/max</th><th>&gt;4 rows</th><th>rows avg/med/p90/max</th><th>chars avg/med/p90/max</th><th>&gt;4 rows</th></tr>' +
      statRow('Now (as generated)', 'now') + statRow('A', 'A') + statRow('B (chip row counts as 1 row)', 'B') + statRow('C', 'C') + '</table>' +
      '<p class="note">Rows = lines under the tags row, tier 1 only. The pose-test duplicates (<code>pt_*</code>, 44 skills) are left out. Same rules, run over the real generated text of every skill in the data. Variant text is made by parsing the generated lines; in the game the split would be made inside <code>describeSkill</code> where each effect type already knows its parts.</p>';
  }
  var CAUSE =
    '<h3>Neden böyle? (kod okuması + ölçüm)</h3>' +
    '<ul>' +
    '<li><b>Tekrar ve bölünme üretimden geliyor.</b> <code>src/game/scenes/BattleScene.ts:2869-2872</code>: skill\'in HER zemin etkisi için ayrı bir "Ground reactions: ..." satırı eklenir (<code>groundReactionHint</code>, <code>src/engine/skill-info.ts:832-840</code>, bir zeminin girdiği bütün tepkimeleri sıralar). Tek koruma <code>rows.some(r =&gt; r[0] === hint)</code> yani satırın TAMAMI birebir aynıysa atlar; Holy Fire ve Holy Ground farklı listeler verdiği için ikisi de girer. Flooded ile tepkime her iki zeminde de ortak olduğundan "Holy water (with Flooded)" iki satırda geçer.</li>' +
    '<li><b>Kaç skill?</b> Veride ' + ST.hintSkills + ' skill zemin tepkime satırı alıyor; bunların yalnız <b>' + ST.splitHint.length + '</b> tanesinde iki zemin var (<code>' + ST.splitHint.join(', ') + '</code>, yani gerçekte yalnız Paladin\'in Judgment\'ı; <code>pt_judgment</code> poz-test kopyası). Yani tekrar/bölünme tek skill\'de; genel sorun satır sayısı ve satır uzunluğu.</li>' +
    '<li><b>Uzunluk.</b> Her etki satırı <code>describeSkill</code>\'te bütün cümlesiyle yazılıyor ("... : enemies standing there are Searing while inside, taking 38% INT (10) damage at the start of each of their turns"). Durum / zemin / DoT satırlarının çoğu "Ad, süre: tam açıklama" biçiminde. Etki türüne göre satır sayısı: ' +
    'hasar-şifa-kalkan ' + ST.lineTypes.effect + ', durum ' + ST.lineTypes.status + ', zemin ' + ST.lineTypes.ground + ', DoT ' + ST.lineTypes.dot + ', koşul cümlesi ' + ST.lineTypes.cond + ', tepkime ' + ST.lineTypes.reaction + ', savaş başı bekleme ' + ST.lineTypes.initcd + ', <b>diğer kural cümleleri ' + ST.lineTypes.other + '</b> (toplam ' + (ST.lineTypes.effect + ST.lineTypes.status + ST.lineTypes.ground + ST.lineTypes.dot + ST.lineTypes.cond + ST.lineTypes.reaction + ST.lineTypes.initcd + ST.lineTypes.other) + ').</li>' +
    '<li><b>Telefonda</b> ipucu savaş HUD\'ının içinde 0,36 ölçekle çiziliyor ve <code>.bh-sktip</code> için telefona özel yazı büyütme yok (CSS okuması, gözle doğrulanmadı): 19 birim yazı ~7 gerçek piksel. Aşağıdaki Phone görünümü bunu aynen gösterir.</li>' +
    '</ul>';

  /* ---------- per-variant "where does it go" tables ---------- */
  function goTable(rows) { return '<table class="t"><tr><th>Information</th><th>Short tip</th><th>Where the rest goes</th></tr>' + rows.map(function (r) { return '<tr><td>' + r[0] + '</td><td>' + r[1] + '</td><td class="' + (r[3] || '') + '">' + r[2] + '</td></tr>'; }).join('') + '</table>'; }
  var CODEX = 'Codex skill page (every <code>describeSkill</code> line, <code>src/wiki/catalog.ts:263</code>); Codex is in the in-game Menu';
  var GO = {
    now: '',
    a: goTable([
      ['Damage / heal / shield numbers', 'Kept. Audience wording shortened: "(on the enemy side: enemies)" becomes "(enemies)"', 'Full wording in More', ''],
      ['Status name + duration (Applies Stun for 2 turns)', 'Kept', 'What the status does ("Skips its next turn"): More, and ' + CODEX, ''],
      ['Ground name, duration, side, per-turn number', 'Kept in one line', 'Full sentence ("enemies standing there are Searing ..."): More, and Codex', ''],
      ['Damage over time: name, duration, per-turn number', 'Kept', 'Sentence incl. "cannot miss or crit": More, and Codex', ''],
      ['Short numeric modifiers (<= 60 chars: "Ignores 50% of armor", "+25% crit chance")', 'Kept', 'Overflow past 4 lines: More', ''],
      ['Cast conditions ("Can also be cast on an empty cell ...")', 'Not in tier 1', 'More, and Codex', ''],
      ['Long rule sentences', 'Not in tier 1', 'More, and Codex', ''],
      ['"Opens on cooldown: N turns"', 'Not in tier 1', 'More; the plate also shows the countdown (to verify in game)', ''],
      ['Ground reactions', 'Not in tier 1', 'ONE merged line in More (no repeat, no split); Codex "Ground reactions" article has the full table (<code>catalog.ts:800</code>); while aiming, reacting cells show the name under the plate (per Codex text)', ''],
      ['Lost completely', '-', 'Nothing. Every removed piece is still reachable in the tip or the Codex.', 'ok'],
    ]),
    b: goTable([
      ['Damage / heal / shield numbers', 'Kept (audience shortened)', 'Codex has the long wording', ''],
      ['Status / ground / damage-over-time', 'One named chip each: icon, name, turns, side, per-turn number', 'Tap / click the chip: its full sentence opens under the chip row (works on touch, 44 px chip). Also Codex', ''],
      ['Short numeric modifiers (<= 60 chars)', 'Kept as lines', 'Codex', ''],
      ['ONE short cast condition (<= 90 chars)', 'Kept as a line', 'Codex', ''],
      ['Longer cast conditions (e.g. Charge: "you then step into the front row ...")', 'Gone from the tip', 'Codex only: ' + (ST.goneB.cond || 0) + ' lines across the data', 'bad'],
      ['Long rule sentences', 'Gone from the tip', 'Codex only: ' + (ST.goneB.other || 0) + ' lines across the data (e.g. all 8 tainted-mana rules of Ley Brand)', 'bad'],
      ['"Opens on cooldown"', 'Gone from the tip', 'Plate countdown (to verify) + Codex', ''],
      ['Ground reactions', 'Gone from the tip', 'Codex article + aim-time label under the plate', ''],
      ['Lost completely', '-', 'Nothing is deleted, but ' + ST.skillsGoneB + ' of ' + ST.total + ' skills lose at least one sentence from the battle screen (Codex only).', 'bad'],
    ]),
    c: goTable([
      ['Damage / heal (max 2 lines, merged to one when short)', 'Kept', 'Codex long wording', ''],
      ['Status / ground / damage-over-time', 'Names + turns + per-turn number on ONE line', 'Sentences: Codex only', 'bad'],
      ['ONE line of: a cast condition (<= 90 chars) or a short numeric modifier (<= 60 chars)', 'Kept (3rd line)', 'Other such lines: Codex only', ''],
      ['Long rule sentences', 'Gone from the tip', 'Codex only: ' + (ST.goneC.other || 0) + ' lines across the data', 'bad'],
      ['Cast conditions beyond the first / too long', 'Gone from the tip', 'Codex only: ' + (ST.goneC.cond || 0) + ' lines', 'bad'],
      ['"Opens on cooldown"', 'Gone from the tip', 'Plate countdown (to verify) + Codex', ''],
      ['Ground reactions', 'Gone from the tip', 'Codex article + aim-time label', ''],
      ['Lost completely', '-', 'Nothing is deleted, but ' + ST.skillsGoneC + ' of ' + ST.total + ' skills lose at least one sentence from the battle screen. No second tier: the player must leave the battle (Menu &gt; Codex) to read it.', 'bad'],
    ]),
  };
  var VTEXT = {
    now: { h: 'Now', tr: 'Bugünkü ipucu, oyunun kendi kodundan çıkan metin ve gerçek CSS. Judgment: 7 satır, Holy water (with Flooded) iki satırda.', rule: null },
    a: { h: 'A · Short list, details behind "More"', rec: true,
      tr: 'Önerilen: ipucunda yalnız "ne olur + sayı" kalır (en çok 4 satır), açıklama cümleleri ve istisnalar tek dokunuşla "More" altında.',
      rule: '<b>Genel kural (A):</b> her etki bir satır: ne yaptığı + sayı + süre. Durum / zemin / DoT için yalnız ad, süre, taraf ve tur başı sayı; "ne işe yarar" cümlesi, koşullar ve istisnalar "More"a gider. Zemin tepkimeleri tek satıra birleşir ve yalnız "More"da durur. Dört satırdan fazlası da "More"a taşar.' },
    b: { h: 'B · Effects as named chips', tr: 'Durum ve zeminler isimli çip olur; cümlesi çipe dokununca açılır. İpucunda sayılar + çipler kalır, uzun kural cümleleri ipucundan çıkar.',
      rule: '<b>Genel kural (B):</b> hasar / şifa / kalkan satırları kalır; her durum, zemin ve DoT tek bir çip (ikon, ad, tur, taraf, tur başı sayı) olur ve cümlesi çipe dokununca altında açılır. Tek kısa koşul cümlesi kalır; geri kalan kural cümleleri ipucunda yok, Codex\'te.' },
    c: { h: 'C · Three lines, the rest in the Codex', tr: 'En sert kesim: en çok 3 satır, ikinci kat yok. Kalan her şey yalnız Codex\'te.',
      rule: '<b>Genel kural (C):</b> en çok 3 satır: (1) hasar ve şifa, kısa ise tek satırda; (2) tüm durum / zemin / DoT adları tur ve sayıyla yan yana; (3) bir koşul ya da bir sayılı çarpan. İkinci kat yok; her şey Codex\'te.' },
  };

  /* ---------- page ---------- */
  function variantSection(v) {
    var si = S.s, sm = D.samples[si], t = VTEXT[v], html = '';
    html += '<section class="sec' + (t.rec ? ' rec' : '') + '" id="v-' + v + '"><h2>' + t.h + '</h2><p class="note tr">' + t.tr + '</p>' + (t.rule ? '<div class="rule">' + t.rule + '</div>' : '');
    html += '<div class="frames">' + frameHtml(si, v, false, v === 'now' ? 'Now' : VNAME[v] + ' · tier 1') + ((v === 'a' || v === 'b') && hasTier2(sm, v) ? frameHtml(si, v, true, VNAME[v] + (v === 'a' ? ' · "More" open' : ' · chip open')) : '') + '</div>';
    html += '<h3>All four skills, tip only (1:1 size; click More / chips)</h3><div class="tipsrow">' + D.samples.map(function (s, i) {
      return '<div class="cell" data-s="' + i + '" data-v="' + v + '" data-open="0"><div class="cap">' + esc(s.label) + '<small>' + esc(s.note) + '</small></div><div class="bh-kit"><div class="tipwrap">' + tipOf(s, v, false) + '</div></div></div>';
    }).join('') + '</div>';
    if (GO[v]) html += '<h3>Where each removed piece goes</h3>' + GO[v];
    return html + '</section>';
  }
  function whole() {
    var h = '';
    h += '<div class="pg-text"><h1>Skill tips: shorter</h1>' +
      '<p class="note tr">Ömer: "çok uzun açıklaması. sadeleştir. skill açıklamaları böyle okuması yorucu olmasın." Tek skill değil, TÜM skill\'ler için genel kural: aşağıdaki üç öneri oyunun kendi ürettiği metne aynı kuralı uygular (el yazısı metin yok). Sayılar (hasar, şifa, süre, menzil, bedel) değişmez; hiçbir mekanik değişmez.</p>' +
      CAUSE + '<h3>Satır ve karakter sayıları (tüm skill\'ler, kural uygulanmış hâli)</h3>' + statsTable() + '</div>';
    var order = S.v ? [S.v] : ['now', 'a', 'b', 'c'];
    order.forEach(function (v) { h += variantSection(v); });
    if (!S.v) {
      h += '<section class="sec pg-text"><h2>Covered screen share</h2><p class="note">Measured with the real CSS: the tip box (without shadow) as a share of the whole screen, per skill, state and screen size. Phone uses <code>html.short</code> and the 0.361 HUD scale like the game. The red dashed rectangle in each frame above is this box.</p>' + coverageTable() + '</section>';
      h += '<section class="sec pg-text"><h2>What the mockup cannot show / needs your decision</h2><ul>' +
        '<li><b>İkinci kat (A ve B) davranışı yeni:</b> bugün ipucu fareyi tutmuyor (<code>.bh-sktip</code> pointer-events: none) ve dokunmatikte uzun basınca (420 ms, <code>battle-hud.ts:428-431</code>) açılıp bırakınca kapanıyor. "More" ve çipler için dokununca sabit kalan ipucu (HUD kart ipuçlarındaki <code>tipPinned</code> gibi) gerekir. Masaüstünde fare plakadan ipucuna kayabilmeli ya da bir tuşla (Shift) açılmalı. Burada yalnız görünümü gösteriyorum.</li>' +
        '<li>Küçük şekil ızgarası (ipucu başlığındaki hedef şekli) çizilmedi; yüksekliği değiştirmez.</li>' +
        '<li>Alt çubuktaki karakter bloğu ve Rest / Skip / Move yaklaşık çizildi (savaş çubuğu başka bir mockupta değişiyor); skill plakaları ve ipucu gerçek sınıf ve CSS.</li>' +
        '<li>Savaş sahnesinde birim yok, yalnız gerçek arka plan (proving grounds).</li></ul></section>';
    }
    return h;
  }

  function bar() {
    var b = '<span class="lbl">Size</span>' + ['169', '219', 'ph'].map(function (k) { return '<button data-z="' + k + '" class="' + (S.z === k ? 'on' : '') + '">' + SIZES[k].label + '</button>'; }).join('') +
      '<span class="lbl">Skill</span>' + D.samples.map(function (s, i) { return '<button data-s="' + i + '" class="' + (S.s === i ? 'on' : '') + '">' + esc(s.label) + '</button>'; }).join('') +
      '<span class="lbl">View</span>' + [[null, 'All'], ['now', 'Now'], ['a', 'A'], ['b', 'B'], ['c', 'C']].map(function (p) { return '<button data-v="' + (p[0] || '') + '" class="' + ((S.v || '') === (p[0] || '') ? 'on' : '') + '">' + p[1] + '</button>'; }).join('') +
      '<span class="lbl">Cover</span><button data-cover="1" class="' + (S.cover ? 'on' : '') + '">Outline</button>';
    $('#mk-bar').innerHTML = b;
  }
  function render() {
    var root = document.documentElement;
    root.classList.toggle('short', S.z === 'ph');
    root.classList.toggle('clean', S.clean);
    root.classList.toggle('showcover', S.cover);
    bar(); writeHash();
    var app = $('#app');
    if (S.clean && S.v) {
      var sm = D.samples[S.s];
      app.innerHTML = '<div class="frames">' + frameHtml(S.s, S.v, S.o, VNAME[S.v]) + (S.o ? '' : '') + '</div>';
    } else app.innerHTML = whole();
    layoutFrames();
  }
  function refreshTip(wrap) {
    var si = +wrap.dataset.s, v = wrap.dataset.v, open = wrap.dataset.open === '1', sm = D.samples[si];
    var box = $('.bh-sktip[data-tipbox]', wrap) || $('.tipwrap', wrap);
    var target = wrap.classList.contains('fr-wrap') ? $('.bp.tip .bh-sktip', wrap) : box;
    target.innerHTML = tipOf(sm, v, open);
    if (wrap.classList.contains('fr-wrap')) layoutFrames();
  }
  document.addEventListener('click', function (e) {
    var t = e.target.closest('button'); if (!t) return;
    if (t.dataset.z) { S.z = t.dataset.z; render(); return; }
    if (t.dataset.s !== undefined && t.closest('#mk-bar')) { S.s = +t.dataset.s; render(); return; }
    if (t.dataset.v !== undefined && t.closest('#mk-bar')) { S.v = t.dataset.v || null; render(); return; }
    if (t.dataset.cover) { S.cover = !S.cover; render(); return; }
    var wrap = t.closest('[data-s][data-v]');
    if (t.classList.contains('st-more') && wrap) { wrap.dataset.open = wrap.dataset.open === '1' ? '0' : '1'; refreshTip(wrap); return; }
    if (t.classList.contains('st-fxc') && wrap) {
      var tip = t.closest('.bt'), det = tip.querySelector('.st-fxd'), on = t.classList.contains('on');
      tip.querySelectorAll('.st-fxc').forEach(function (x) { x.classList.remove('on'); });
      if (on) det.hidden = true; else { t.classList.add('on'); det.hidden = false; det.innerHTML = '<span class="dia"></span><div class="tx"></div>'; det.lastChild.textContent = t.dataset.detail; }
      if (wrap.classList.contains('fr-wrap')) layoutFrames();
    }
  });
  var rz; window.addEventListener('resize', function () { clearTimeout(rz); rz = setTimeout(layoutFrames, 80); });
  readHash(); render();
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(layoutFrames);
  window.addEventListener('load', layoutFrames);
})();
